  { o: "Варвара Ольховская, инженер каскада", s: "Вода в нижних кварталах", m: [
    ["Смотритель водокачки, нижние кварталы", "Вода в нижних кварталах", "Варвара, вода опять мутнеет. Люди спрашивают, не обманывают ли их с платой. Что с биофильтром?"],
    ["*", "Re: Вода в нижних кварталах", "Биофильтр ушёл с полей за водой, Ильин пошёл за ним. Держим каскад на старых отстойниках: мутно, но пить можно. Скажи людям: не обманываем. Чиним."],
    ["Смотритель водокачки, нижние кварталы", "Re: Re: Вода в нижних кварталах", "Сказал. Поверили — не потому, что вода чистая, а потому, что ты не врёшь. Держитесь там."] ] },
  { o: "Нил Сухов, дежурный Главного журнала", s: "Сверка", m: [
    ["Лаборант", "Сверка", "Дежурный Сухов. Прошу поставить плёнку «Голос Академика» на третью сверку пробы номер семь."],
    ["*", "Re: Сверка", "Ставлю. Третья сверка за сутки. Что-то не так с первыми двумя?"],
    ["Лаборант", "Re: Re: Сверка", "С ними всё так. Совпадений нет. Прошу поставить в третий раз. И потом не перематывайте сразу. Я ещё послушаю."] ] },
  { o: "Дарья Мокеева, виварщица", s: "Обход у края", m: [
    ["Агния Берг", "Обход у края", "Даша, совет просит обход у края Трещины. Возьми бурых. Нужны пробы с камня."],
    ["*", "Re: Обход у края", "Возьму Сторожа и двоих молодых. Бурые пойдут первыми, как всегда. Если задержусь — кормите Сторожа сами, он капризный."],
    ["Агния Берг", "Re: Re: Обход у края", "Бурые вернулись втроём. Тебя нет. Сторож лёг у двери и не ест. Даша, возвращайся. Пожалуйста. Без тебя я не знаю, как с ними говорить."] ] },
  { o: "Савва Глотов, механик", s: "Чертежи", m: [
    ["Лаборант", "Чертежи", "Механик Глотов. Запрошены старые чертежи машин из планшетов первых. Цель запроса?"],
    ["*", "Re: Чертежи", "Хочу собрать машину, которая будет кормить виварий, если людей не хватит. Добрую. Без оружия."],
    ["Лаборант", "Re: Re: Чертежи", "Чертежи выданы. Примечание: в чертежах первых машин без оружия нет. Придётся придумать самому. Удачи."],
    ["*", "Re: Re: Re: Чертежи", "Придумал. Назвал Кормилицей. Она уже гладит бурых щёткой. Запиши, что она первая."] ] },
  { o: "Агния Берг, заведующая Культуральным корпусом", s: "Кабинет Академика", m: [
    ["Уборщица Кабинета Академика", "Кабинет Академика", "Агния Петровна, халат в кабинете пожелтел от времени. Шить новый или стирать старый?"],
    ["*", "Re: Кабинет Академика", "Шей новый, по старой мерке. А старый не выбрасывай, сложи в шкаф. Вдруг он придёт и захочет свой."],
    ["Уборщица Кабинета Академика", "Re: Re: Кабинет Академика", "Сшила. Старый сложила. За стол не садилась. Хотя очень хотелось: стул удобный."] ] }
